\begin{definition}
For $x \in \mathbb{R}$,
\begin{equation}
  |x| =
  \begin{cases}
    x & \text{if } x \geq 0 \\
    -x & \text{if } x < 0
  \end{cases}
\end{equation}
\end{definition}

\begin{theorem}
For all $x, y \in \mathbb{R}$, $|x + y| \leq |x| + |y|$.
\end{theorem}

\begin{proof}
From the definition, $-|x| \leq x \leq |x|$ and $-|y| \leq y \leq |y|$.
Adding these,
\begin{align}
  -(|x| + |y|) \leq x + y \leq |x| + |y|,
\end{align}
hence $|x + y| \leq |x| + |y|$.
\end{proof}
